<template><div><div class="page-head"><div><h1>Activity logs</h1><p>Immutable administrative actions for accountability and review.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date and time</th><th>Administrator</th><th>Action</th><th>Target</th><th>IP address</th></tr></thead><tbody><tr v-for="l in page.data" :key="l.id"><td>{{new Date(l.created_at).toLocaleString()}}</td><td><strong>{{l.admin?.name||'Deleted administrator'}}</strong><br>{{l.admin?.email}}</td><td>{{format(l.action)}}</td><td>{{shortType(l.subject_type)}} {{l.subject_id||''}}</td><td>{{l.ip_address||'—'}}</td></tr></tbody></table></div><div class="pagination"><button class="secondary" :disabled="!page.prev_page_url" @click="load(page.current_page-1)">Previous</button><button class="secondary" :disabled="!page.next_page_url" @click="load(page.current_page+1)">Next</button></div></section></div></template>
<script setup>import{onMounted,ref}from'vue';import api from'../utils/api';const page=ref({data:[]}),format=v=>(v||'').replaceAll('.',' · ').replaceAll('_',' '),shortType=v=>(v||'').split('\\').pop();const load=async(p=1)=>page.value=(await api.get('/admin/activity-logs',{params:{page:p}})).data;onMounted(load)</script>
